<?php

declare(strict_types=1);

namespace App\Enums;

enum MessageType: string
{
    case Text = 'text';
    case Image = 'image';
    case Audio = 'audio';
    case Video = 'video';
    case File = 'file';
    case Template = 'template';
    case Note = 'note';
    case System = 'system';

    /**
     * System messages are generated by Dukavo itself (assignment, status
     * changes) and must never be persisted from client input.
     */
    public function isSystemGenerated(): bool
    {
        return $this === self::System;
    }

    /**
     * Notes are written by the team for the team. They are never handed to a
     * channel provider and never rendered as customer-visible messages.
     */
    public function isInternal(): bool
    {
        return $this === self::Note;
    }

    public function isMedia(): bool
    {
        return in_array($this, [self::Image, self::Audio, self::Video, self::File], true);
    }
}
